package USTGlobal.SeleniumJava;

public class SwitchCaseEg {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int num = 10;
		
		switch(num) {
		
		case 1: System.out.println("The number is 1");
		//break will stop the execution of the program
		break;
		
		case 2: System.out.println("The number is 2");
		break;
		
		case 3: System.out.println("The number is 3");
		break;
		
		case 4: System.out.println("The number is 4");
		break;
		
		default: System.out.println("The number is not 1 or 2 or 3 or 4");
		
		
		
		}
	}

}
